import { expect, test, uniqueName } from "../../fixtures";

test.describe("VEN-04: vendor names are unique per tenant, not globally", () => {
  test(
    "the same vendor name is allowed in a different tenant",
    { tag: "@VEN-04" },
    async ({ apiAs }) => {
      // Arrange: a vendor with the same name already exists in another tenant.
      // The name is generated so parallel runs don't collide, but both sides use the same name.
      const name = uniqueName("Acme Freight");
      const globex = await apiAs("otherTenant");
      const seeded = await globex.post("/api/vendors", {
        data: { name, category: "logistics", contact_email: "ops@globex.example" },
      });
      expect(seeded.status(), "seed Globex vendor").toBe(201);

      const member = await apiAs("member");

      // Act
      const response = await member.post("/api/vendors", {
        data: { name, category: "logistics", contact_email: "ops@acmefreight.example" },
      });

      // Assert
      expect(response.status()).toBe(201);
      const vendor = await response.json();
      expect(vendor.name).toBe(name);
      expect(vendor.category).toBe("logistics");
      expect(vendor.contact_email).toBe("ops@acmefreight.example");
      expect(vendor.id).not.toBe((await seeded.json()).id);
    },
  );
});
